import type { ComponentType } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, fn, userEvent, waitFor, within } from 'storybook/test';
import { Button } from '../Button';
import { FloatingContainer } from '../FloatingContainer';
import { FullWidthFrame } from '../../stories/kit/FullWidthFrame';
import { HomeIndicatorMock } from '../../stories/kit/Phone';
import { Disclaimer, type DisclaimerCheckboxProps } from './Disclaimer';

const meta = {
  title: 'Components/Disclaimer',
  component: Disclaimer as unknown as ComponentType<DisclaimerCheckboxProps>,
  parameters: {
    design: { type: 'figma', url: 'https://www.figma.com/design/Enj0CUGKB1uJvXiWt7Vu8P/Design-System---Mtravel-2.0?node-id=777-6091' },
    layout: 'fullscreen',
  },
  decorators: [
    (Story) => (
      <FullWidthFrame>
        <Story />
      </FullWidthFrame>
    ),
  ],
  args: {
    variant: 'checkbox',
    children: 'Я подтверждаю, что ознакомлен(а) и соглашаюсь с правилами предоставления сервиса MTravel',
    onCheckedChange: fn(),
  },
  argTypes: {
    variant: { control: 'inline-radio', options: ['checkbox', 'center'] },
    children: { control: 'text' },
  },
} satisfies Meta<DisclaimerCheckboxProps>;

export default meta;
type Story = StoryObj<typeof meta>;

const Terms = () => (
  <>
    Я подтверждаю, что ознакомлен(а) и соглашаюсь с <a href="#terms">правилами предоставления сервиса MTravel</a>
  </>
);

/** Юридическая строка под главной кнопкой. */
export const Playground: Story = {};

/** The Figma set 777:6091: Property 1 = Default (checkbox) | Center disclamer. */
export const Variants: Story = {
  name: 'Варианты',
  parameters: { controls: { disable: true } },
  render: () => (
    <div style={{ display: 'grid', gap: 16 }}>
      <Disclaimer>
        <Terms />
      </Disclaimer>
      <Disclaimer defaultChecked>
        <Terms />
      </Disclaimer>
      <Disclaimer disabled>
        <Terms />
      </Disclaimer>
      <Disclaimer variant="center">
        Нажимая «Оплатить», вы соглашаетесь с <a href="#terms">правилами предоставления сервиса MTravel</a>
      </Disclaimer>
    </div>
  ),
};

/** Payment screen: the disclaimer sits over the main button of the bottom bar (Figma 1338:107637). */
export const CaseCheckout: Story = {
  name: 'Кейс: оформление заказа',
  parameters: { controls: { disable: true } },
  globals: { viewport: { value: 'mbank393', isRotated: false } },
  render: () => (
    <FloatingContainer
      shadow={false}
      layout="column"
      homeIndicator={<HomeIndicatorMock />}
    >
      <Disclaimer>
        <Terms />
      </Disclaimer>
      <Button fullWidth size={52}>
        Оплатить 12 300 ⃀
      </Button>
    </FloatingContainer>
  ),
};

/** Interaction test: a tap on the text toggles the checkbox, a tap on the link does not. */
export const BehaviourTest: Story = {
  name: 'Тест: тап по тексту и по ссылке',
  parameters: { controls: { disable: true } },
  render: (args) => (
    <Disclaimer {...args}>
      <Terms />
    </Disclaimer>
  ),
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    const box = canvas.getByRole('checkbox');
    await expect(box).not.toBeChecked();
    await userEvent.click(canvas.getByText(/Я подтверждаю/));
    await waitFor(() => expect(box).toBeChecked());
    await expect(args.onCheckedChange).toHaveBeenLastCalledWith(true);
    const link = canvas.getByRole('link', { name: /правилами/ });
    link.addEventListener('click', (e) => e.preventDefault());
    await userEvent.click(link);
    await expect(box).toBeChecked();
  },
};

/** Pressing a link inside the text shows the pressed colour from pointer-down (not only `:active`, which iOS WebKit skips). */
export const LinkPressTest: Story = {
  name: 'Тест: нажатие на ссылку',
  parameters: { controls: { disable: true } },
  render: () => (
    <Disclaimer variant="center">
      Нажимая «Оплатить», вы соглашаетесь с <a href="#terms">правилами предоставления сервиса MTravel</a>
    </Disclaimer>
  ),
  play: async ({ canvasElement }) => {
    const link = within(canvasElement).getByRole('link', { name: /правилами/ });
    link.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, button: 0 }));
    await waitFor(() => expect(link).toHaveAttribute('data-pressed'));
    link.dispatchEvent(new PointerEvent('pointerup', { bubbles: true, button: 0 }));
    await waitFor(() => expect(link).not.toHaveAttribute('data-pressed'));
  },
};

